// Prepends the standard "Code generated ... DO NOT EDIT." marker to a file
// openapi-typescript wrote, so tools and reviewers treat it as generated.
import { readFileSync, writeFileSync } from "node:fs";

const MARKER =
  "// Code generated by openapi-typescript from api/openapi/v1/kosha.openapi.json. DO NOT EDIT.\n" +
  "// Regenerate with `make clients-gen`.\n\n";

for (const file of process.argv.slice(2)) {
  const text = readFileSync(file, "utf8");
  if (!text.startsWith(MARKER)) writeFileSync(file, MARKER + text);
}
